package com.shop.elpsy;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.autoconfigure.web.servlet.MockMvcPrint;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

/** Complete security chain + real isolated MySQL/Redis, never a production database. */
@SpringBootTest @AutoConfigureMockMvc(print=MockMvcPrint.NONE) @ActiveProfiles("demo")
@EnabledIfEnvironmentVariable(named="SHOP_MYSQL_INTEGRATION",matches="true")
class CatalogMasterIntegrationTest {
    @Autowired MockMvc mvc;
    @Autowired ObjectMapper json;
    @org.springframework.boot.test.mock.mockito.SpyBean JdbcTemplate jdbc;
    @Autowired com.shop.elpsy.service.CatalogMasterService masters;
    @Autowired com.shop.elpsy.service.CatalogService catalog;
    @Autowired StringRedisTemplate redis;
    private final Set<String> ids=ConcurrentHashMap.newKeySet();
    private final Set<String> sessionKeys=ConcurrentHashMap.newKeySet();
    record Client(String csrf,List<Cookie> cookies) {}
    private Cookie cookie(MvcResult r,String name){var header=r.getResponse().getHeaders("Set-Cookie").stream().filter(h->h.startsWith(name+"=")).findFirst().orElseThrow();return new Cookie(name,header.split(";",2)[0].substring(name.length()+1));}
    private JsonNode data(MvcResult r) throws Exception{return json.readTree(r.getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).path("data");}
    private MvcResult call(Client c,String method,String path,Object body) throws Exception{
        var b=request(org.springframework.http.HttpMethod.valueOf(method),"/ELPSY/api"+path).contextPath("/ELPSY").servletPath("/api"+path.split("\\?",2)[0]);
        if(c!=null){b.cookie(c.cookies().toArray(Cookie[]::new));if(!method.equals("GET"))b.header("X-XSRF-TOKEN",c.csrf());}
        if(body!=null)b.contentType("application/json").content(json.writeValueAsBytes(body));
        return mvc.perform(b).andReturn();
    }
    private Client guest() throws Exception{var r=call(null,"GET","/auth/csrf",null);return new Client(data(r).path("token").asText(),List.of(cookie(r,"XSRF-TOKEN")));}
    private Client staff(boolean admin) throws Exception{
        var c=guest();String device=UUID.randomUUID().toString(),name=admin?"shop_admin":"shop_staff";
        var r=mvc.perform(post("/ELPSY/api/admin/login").contextPath("/ELPSY").servletPath("/api/admin/login").cookie(c.cookies().toArray(Cookie[]::new)).header("X-XSRF-TOKEN",c.csrf()).param("username",name).param("password",System.getenv(admin?"DEMO_ADMIN_PASSWORD":"DEMO_STAFF_PASSWORD")).param("deviceId",device)).andReturn();assertEquals(200,r.getResponse().getStatus());
        sessionKeys.add("shop:session:"+data(r).path("id").asInt()+":"+device);
        return new Client(c.csrf(),List.of(c.cookies().get(0),cookie(r,"accessToken"),cookie(r,"refreshToken")));
    }
    private Map<String,Object> sku(String code,boolean enabled){return new HashMap<>(Map.of("code",code,"label","初回限定款","priceTwd",1280,"enabled",enabled));}
    private Map<String,Object> product(List<Map<String,Object>> skus){return new HashMap<>(Map.of("title","integration collection "+UUID.randomUUID(),"brand","ELPSY","category","公仔","description","<script>資料是文字</script>","expectedVersion",0,"skus",skus));}
    private String code(){return "TEST-"+UUID.randomUUID();}
    private JsonNode create(Client c,Map<String,Object> input) throws Exception{var r=call(c,"POST","/admin/products",input);assertEquals(201,r.getResponse().getStatus(),r.getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));var p=data(r);ids.add(p.path("id").asText());return p;}
    private Map<String,Object> write(JsonNode p){return new HashMap<>(Map.of("title",p.path("title").asText(),"brand",p.path("brand").asText(),"category",p.path("category").asText(),"description",p.path("description").asText(),"expectedVersion",p.path("version").asInt(),"skus",json.convertValue(p.path("skus"),List.class)));}
    private MvcResult publish(Client c,JsonNode p,boolean yes) throws Exception{return call(c,"PATCH","/admin/products/"+p.path("id").asText()+"/publication",Map.of("expectedVersion",p.path("version").asInt(),"published",yes));}
    private final Set<String> masterIds=new HashSet<>();
    @AfterEach void cleanup(){for(String id:ids)jdbc.update("UPDATE catalog_product SET status='ARCHIVED' WHERE id=?",id);for(String id:masterIds)for(String t:List.of("catalog_brand","catalog_category","catalog_work"))jdbc.update("UPDATE "+t+" SET enabled=FALSE WHERE id=?",id);if(!sessionKeys.isEmpty())redis.delete(sessionKeys);}
    private Map<String,Object> masterWrite(String name,int version,boolean enabled){return new HashMap<>(Map.of("name",name,"description","主檔驗證","enabled",enabled,"expectedVersion",version,"requestId",UUID.randomUUID().toString(),"note","合成測試原因"));}
    private JsonNode master(Client a,String kind)throws Exception{var r=call(a,"POST","/admin/masters/"+kind,masterWrite("Test "+UUID.randomUUID(),0,true));assertEquals(201,r.getResponse().getStatus(),r.getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));var m=data(r).path("current");masterIds.add(m.path("id").asText());return m;}
    private Map<String,Object> associated(JsonNode brand,JsonNode category,JsonNode work){var p=product(List.of(sku(code(),true)));p.remove("brand");p.remove("category");p.put("brandId",brand.path("id").asText());p.put("categoryId",category.path("id").asText());if(work!=null)p.put("workId",work.path("id").asText());return p;}
    private String path(JsonNode m){return "/admin/masters/"+m.path("kind").asText()+"/"+m.path("id").asText();}
    private Map<String,Object> edit(JsonNode m,boolean enabled){return masterWrite(m.path("name").asText(),m.path("version").asInt(),enabled);}
    private Map<String,Object> idWrite(JsonNode p){var b=write(p);b.remove("brand");b.remove("category");b.put("brandId",p.path("brandId").asText());b.put("categoryId",p.path("categoryId").asText());b.put("workId",p.path("workId").isNull()?null:p.path("workId").asText());return b;}
    @Test void createReplayConflictAndSafeAudit()throws Exception{var a=staff(true);var b=masterWrite("Name "+UUID.randomUUID(),0,true);var r=call(a,"POST","/admin/masters/BRAND",b);assertEquals(201,r.getResponse().getStatus());var m=data(r).path("current");masterIds.add(m.path("id").asText());assertFalse(data(r).path("event").has("fingerprint"));assertEquals(jdbc.queryForObject("SELECT created_at FROM catalog_master_event WHERE request_id=?",(row,n)->row.getObject(1,java.time.LocalDateTime.class),b.get("requestId")),java.time.LocalDateTime.parse(data(r).path("event").path("createdAt").asText()));assertEquals(200,call(a,"POST","/admin/masters/BRAND",b).getResponse().getStatus());assertEquals(409,call(a,"POST","/admin/masters/WORK",b).getResponse().getStatus());b.put("name","different");assertEquals(409,call(a,"POST","/admin/masters/BRAND",b).getResponse().getStatus());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_master_event WHERE request_id=?",Integer.class,b.get("requestId")));}
    @Test void namesAreTrimmedAndCaseSensitiveWithoutDuplicateAutoMerge()throws Exception{var a=staff(true);String name="Name "+UUID.randomUUID();var first=call(a,"POST","/admin/masters/BRAND",masterWrite("  "+name+"  ",0,true));assertEquals(201,first.getResponse().getStatus());masterIds.add(data(first).path("current").path("id").asText());assertEquals(name,data(first).path("current").path("name").asText());assertEquals(409,call(a,"POST","/admin/masters/BRAND",masterWrite(name,0,true)).getResponse().getStatus());var lower=call(a,"POST","/admin/masters/BRAND",masterWrite(name.toLowerCase(Locale.ROOT),0,true));assertEquals(201,lower.getResponse().getStatus());masterIds.add(data(lower).path("current").path("id").asText());}
    @Test void staleWritesCrossTargetAndCurrentReplay()throws Exception{var a=staff(true);var m=master(a,"WORK");var other=master(a,"WORK");var b=edit(m,true);b.put("name","Renamed "+UUID.randomUUID());assertEquals(201,call(a,"PUT",path(m),b).getResponse().getStatus());assertEquals(200,call(a,"PUT",path(m),b).getResponse().getStatus());assertEquals(409,call(a,"PUT",path(other),b).getResponse().getStatus());b.put("requestId",UUID.randomUUID().toString());assertEquals(409,call(a,"PUT",path(m),b).getResponse().getStatus());assertEquals(0,masters.find("WORK",other.path("id").asText()).version());}
    @Test void readOnlyStaffCsrfAndUnknownFields()throws Exception{var a=staff(true);var e=staff(false);var b=masterWrite("Denied "+UUID.randomUUID(),0,true);assertEquals(200,call(e,"GET","/admin/masters?kind=WORK",null).getResponse().getStatus());assertEquals(200,call(e,"GET","/admin/masters/options?kind=CATEGORY",null).getResponse().getStatus());assertEquals(200,call(e,"GET","/admin/masters/audit",null).getResponse().getStatus());assertEquals(403,call(e,"POST","/admin/masters/BRAND",b).getResponse().getStatus());assertEquals(401,call(null,"GET","/admin/masters",null).getResponse().getStatus());assertEquals(403,call(new Client("wrong",a.cookies()),"POST","/admin/masters/BRAND",b).getResponse().getStatus());for(String key:List.of("actorId","id","version","url")){var bad=new HashMap<>(b);bad.put(key,"spoof");assertEquals(400,call(a,"POST","/admin/masters/BRAND",bad).getResponse().getStatus());}assertEquals(400,call(a,"GET","/admin/masters?kind=BAD",null).getResponse().getStatus());assertEquals(400,call(a,"GET","/admin/masters?pageSize=51",null).getResponse().getStatus());assertEquals(400,call(a,"GET","/admin/masters/audit?page=0",null).getResponse().getStatus());assertEquals(403,call(a,"DELETE","/admin/masters/audit",null).getResponse().getStatus());}
    @Test void liveGrantRevocationAlsoGuardsDirectService()throws Exception{var a=staff(true);jdbc.update("DELETE FROM role_permission WHERE role_id=1 AND permission_id=202");try{var actor=new com.shop.elpsy.pojo.CustomUserDetails("spoof",jdbc.queryForObject("SELECT id FROM user WHERE username='shop_admin'",Integer.class),List.of());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->masters.save("BRAND",null,new com.shop.elpsy.dto.MasterPayloads.Write("Denied","",true,0,UUID.randomUUID().toString(),"test"),actor));assertEquals(403,call(a,"POST","/admin/masters/BRAND",masterWrite("Denied",0,true)).getResponse().getStatus());}finally{jdbc.update("INSERT INTO role_permission VALUES(1,202)");}}
    @Test void productIdsResolveLiveNamesAndWrongKindIsRejected()throws Exception{var a=staff(true);var b=master(a,"BRAND");var c=master(a,"CATEGORY");var w=master(a,"WORK");var input=associated(b,c,w);var p=create(a,input);assertEquals(b.path("id"),p.path("brandId"));assertEquals(w.path("name"),p.path("work"));var rename=edit(b,true);rename.put("name","Changed "+UUID.randomUUID());assertEquals(201,call(a,"PUT",path(b),rename).getResponse().getStatus());var now=data(call(a,"GET","/admin/products/"+p.path("id").asText(),null));assertEquals(0,now.path("version").asInt());assertEquals(rename.get("name"),now.path("brand").asText());assertEquals(b.path("name").asText(),jdbc.queryForObject("SELECT brand FROM catalog_product WHERE id=?",String.class,p.path("id").asText()));input.put("brandId",c.path("id").asText());assertEquals(404,call(a,"POST","/admin/products",input).getResponse().getStatus());assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE catalog_product SET brand_id=? WHERE id=?",c.path("id").asText(),p.path("id").asText()));}
    @Test void legacyCannotCreateMasterAndMixedStaleLabelsRejected()throws Exception{var a=staff(true);var input=product(List.of(sku(code(),true)));input.put("brand","Unknown "+UUID.randomUUID());assertEquals(409,call(a,"POST","/admin/products",input).getResponse().getStatus());var b=master(a,"BRAND");var c=master(a,"CATEGORY");input=associated(b,c,null);input.put("brand","stale label");assertEquals(409,call(a,"POST","/admin/products",input).getResponse().getStatus());input.remove("brand");input.remove("categoryId");assertEquals(400,call(a,"POST","/admin/products",input).getResponse().getStatus());}
    @Test void disabledDraftAssociationRetainedButNewAssignmentAndPublishFail()throws Exception{var a=staff(true);var b=master(a,"BRAND");var c=master(a,"CATEGORY");var w=master(a,"WORK");var p=create(a,associated(b,c,w));assertEquals(201,call(a,"PUT",path(w),edit(w,false)).getResponse().getStatus());var body=idWrite(p);body.put("title","Edit with retained disabled work");p=data(call(a,"PUT","/admin/products/"+p.path("id").asText(),body));assertEquals(w.path("id"),p.path("workId"));assertEquals(409,publish(a,p,true).getResponse().getStatus());assertEquals(409,call(a,"POST","/admin/products",associated(b,c,w)).getResponse().getStatus());body=idWrite(p);body.put("workId",null);var r=call(a,"PUT","/admin/products/"+p.path("id").asText(),body);assertEquals(200,r.getResponse().getStatus());p=data(r);assertTrue(p.path("workId").isNull());assertEquals(200,publish(a,p,true).getResponse().getStatus());}
    @Test void publishedReferencesPreventDisablingAllThreeKinds()throws Exception{var a=staff(true);var b=master(a,"BRAND");var c=master(a,"CATEGORY");var w=master(a,"WORK");var p=create(a,associated(b,c,w));p=data(publish(a,p,true));for(var m:List.of(b,c,w))assertEquals(409,call(a,"PUT",path(m),edit(m,false)).getResponse().getStatus());var publicData=data(call(null,"GET","/catalog/products/"+p.path("id").asText(),null));assertEquals(w.path("name"),publicData.path("work"));assertFalse(publicData.has("workId"));assertFalse(publicData.has("enabled"));p=data(publish(a,p,false));for(var m:List.of(b,c,w))assertEquals(201,call(a,"PUT",path(m),edit(m,false)).getResponse().getStatus());}
    @Test void auditFailureRollsBackEntityVersionAndRequest()throws Exception{var a=staff(true);var m=master(a,"WORK");var b=edit(m,false);org.mockito.Mockito.doThrow(new org.springframework.dao.DataAccessResourceFailureException("synthetic audit failure")).when(jdbc).update(org.mockito.ArgumentMatchers.startsWith("INSERT INTO catalog_master_event"),org.mockito.ArgumentMatchers.any(Object[].class));try{assertEquals(500,call(a,"PUT",path(m),b).getResponse().getStatus());assertEquals(0,masters.find("WORK",m.path("id").asText()).version());assertTrue(masters.find("WORK",m.path("id").asText()).enabled());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_master_event WHERE request_id=?",Integer.class,b.get("requestId")));}finally{org.mockito.Mockito.reset(jdbc);}}
    @Test void competingPublicationAndDisableCannotProducePublishedDisabledMaster()throws Exception{var a=staff(true);var employee=staff(false);jdbc.update("INSERT INTO role_permission VALUES(2,203)");var b=master(a,"BRAND");var c=master(a,"CATEGORY");var p=create(a,associated(b,c,null));var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var publish=pool.submit(()->{start.await();return publish(a,p,true).getResponse().getStatus();});var disable=pool.submit(()->{start.await();return call(employee,"PUT",path(b),edit(b,false)).getResponse().getStatus();});start.countDown();var statuses=List.of(publish.get(15,TimeUnit.SECONDS),disable.get(15,TimeUnit.SECONDS));assertTrue(statuses.contains(409));assertTrue(statuses.contains(200)||statuses.contains(201));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_product p JOIN catalog_brand b ON b.id=p.brand_id WHERE p.id=? AND p.status='PUBLISHED' AND b.enabled=FALSE",Integer.class,p.path("id").asText()));}finally{jdbc.update("DELETE FROM role_permission WHERE role_id=2 AND permission_id=203");pool.shutdownNow();}}
}
